WITH base AS (SELECT * FROM web_events WHERE page = '/cart'), summary AS (SELECT MONTH(event_time) AS event_month, CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END AS event_cohort, AVG(duration_sec) AS avg_duration_sec, SUM(duration_sec) AS total_duration_sec FROM base GROUP BY MONTH(event_time), CASE WHEN YEAR(event_time) < 2024 THEN 'before_2024' WHEN YEAR(event_time) = 2024 THEN '2024' ELSE 'after_2024' END) SELECT * FROM summary WHERE total_duration_sec >= 2200 ORDER BY 4 DESC, event_cohort
